scan_para=function(id, r){
  if(id=="linkinput"){
    scan_impl(id, "#"+r+"#");}
  else{
   document.getElementById(id).value=r;
    }
};

editWebs=function(){
	var max=$("#需发数量").val()*1
	var val=$("#发货数量").val()*1
	if(val==max){
             //两者相等直接返回
		showModelData(null);
	}else{
           //重新计算需发数量
          $("#需发数量").val(max-val);
          $("#库位").val("");
          $("#发货数量").val("");
          $("#序列号").val("");
          $("#选择库存").val("");
           //需要手动刷新详情界面
           var con = plus.webview.getWebviewById('contentlist');
	   mui.fire(con,'contentlist_local',{});
	}
}


beforeFunction=function(sta,id){
var a=$("#数据检查").val();
if(a!="OK"&&( sta=="new"||sta=="autoSave")){
alert(a);
return true;
}
else
{return false;}};

repeatTime=function(id){
   if(id=="linkpreprocess")
    return 10
    return 1
}

limitTimeAction=function(id){
   if(id=="linkpreprocess")
alert("lang:{zh:10秒内不可重复点击,en:Cannot click repeatedly within 10 seconds,de:Nicht wiederholt klicken (10s)}");
}

//删除后自动刷新
afterFunction=function(id){ 
